function Write-EntraCAErrorLog{[CmdletBinding()]param([Parameter(Mandatory)][string]$Message,[System.Management.Automation.ErrorRecord]$ErrorRecord,[string]$LogRoot=(Join-Path $PSScriptRoot "../../Logs/Errors"));if(-not (Test-Path $LogRoot)){New-Item -ItemType Directory -Path $LogRoot -Force|Out-Null};$e=[PSCustomObject]@{Timestamp=(Get-Date).ToString("o");Message=$Message;Exception=if($ErrorRecord){$ErrorRecord.Exception.Message}else{$null};Category=if($ErrorRecord){$ErrorRecord.CategoryInfo.Category}else{$null}};$e|ConvertTo-Json -Compress|Add-Content -Path (Join-Path $LogRoot ("errors-{0}.log" -f (Get-Date -Format "yyyy-MM-dd"))) -Encoding UTF8;Write-Host "[ERROR] $Message" -ForegroundColor Red}